const COMMON_BRIEF = ['Размеры и количество деталей', 'Назначение и место установки', 'Кромка, отверстия и вырезы'];
const CUT = ['cutting-machining', 'edge-finishing'];
const DECOR = ['cutting-machining', 'edge-finishing', 'surface-decoration'];
const THERMAL = ['cutting-machining', 'edge-finishing', 'thermal-forming'];
const LAMINATION = ['lamination', 'edge-finishing'];

function branch(id, title, intro, image, children, extra = {}) {
  return { id, title, intro, image, children, ...extra };
}

function material(id, title, intro, image, properties, extra = {}) {
  return {
    id, title, intro, image,
    result: extra.result || intro,
    brief: extra.brief || COMMON_BRIEF,
    notes: extra.notes || ['Форму детали и обработку кромки согласуем по чертежу.'],
    tags: extra.tags || [properties.transparency, properties.finish, properties.color].filter(Boolean),
    properties,
    serviceIds: extra.serviceIds || CUT,
    ...extra,
  };
}

