// Explicit editorial variants: every entry is a meaningful choice, not a product
// of all colours × surfaces × treatments. Existing paths remain category pages.
function splitMaterial(family, id, options, intro) {
  const find = node => node.id === id ? node : (node.children || []).map(find).find(Boolean);
  const source = find(family);
  if (!source || source.children) throw new Error(`Material leaf not found: ${id}`);
  const children = options.map(option => material(
    option.id, option.title, option.intro, option.image || source.image,
    { ...source.properties, ...option.properties },
    { brief: source.brief, notes: source.notes, serviceIds: source.serviceIds, ...option.extra },
  ));
  const parent = branch(source.id, source.title, intro || source.intro, source.image, children,
    { serviceIds: source.serviceIds });
  Object.keys(source).forEach(key => delete source[key]);
  Object.assign(source, parent);
}

